func (ledger *Ledger) readObjectLimit(ctx context.Context, bucket, objectName string, maximum int) (StoredRecord, error) {
	if ledger.config.DerivedStartup != nil {
		authority := *ledger.config.DerivedStartup
		if ledger.now().Before(authority.ExpiresAt()) {
			if err := authority.VerifyCurrent(ctx, ledger.now()); err != nil {
				return StoredRecord{}, err
			}
		} else if _, err := authority.historical(ctx, authority.Wire()); err != nil {
			return StoredRecord{}, err
		}
	}
	response, err := ledger.client.GetObject(ociclient.RequestContext(ctx), objectstorage.GetObjectRequest{
		NamespaceName: new(ledger.config.Namespace),
		BucketName:    new(bucket),
		ObjectName:    new(objectName),
	})
	if err != nil {
		if serviceErr, ok := errors.AsType[objectStorageServiceError](err); ok && serviceErr.GetHTTPStatusCode() == http.StatusNotFound {
			return StoredRecord{}, ErrRecordMissing
		}
		return StoredRecord{}, fmt.Errorf("read exact bootstrap object: %w", err)
	}
	if response.Content == nil {
		return StoredRecord{}, errors.New("bootstrap object response has no body")
	}
	if response.ContentLength == nil || *response.ContentLength < 1 || *response.ContentLength > int64(maximum) {
		response.Content.Close()
		return StoredRecord{}, errors.New("bootstrap object has missing or invalid content length")
	}
	body, err := io.ReadAll(io.LimitReader(response.Content, int64(maximum)+1))
	closeErr := response.Content.Close()
	if err := errors.Join(err, closeErr); err != nil {
		return StoredRecord{}, fmt.Errorf("read bootstrap object body: %w", err)
	}
	if len(body) != int(*response.ContentLength) || len(body) > maximum {
		return StoredRecord{}, errors.New("bootstrap object body length does not match its metadata")
	}
	if response.ETag == nil || strings.TrimSpace(*response.ETag) == "" || response.LastModified == nil {
		return StoredRecord{}, errors.New("bootstrap object is missing ETag or Last-Modified metadata")
	}
	if response.RawResponse == nil {
		return StoredRecord{}, errors.New("bootstrap object response is missing server headers")
	}
	serverDate, err := http.ParseTime(response.RawResponse.Header.Get("Date"))
	if err != nil {
		return StoredRecord{}, errors.New("bootstrap object response has a missing or invalid server Date")

source_inventory.text:
var completedRecipeSourceDirs = []string{
	"cmd/terrascale-orchestrator",
	"deploy/image",
	"deploy/systemd",
	"internal/app",
	"internal/bootstrap",
	"internal/bootstrapstart",
	"internal/cli",
	"internal/commandio",
	"internal/release",
	"internal/trust",
	"tests/firecracker/production",
}

// CurrentCompletedSourcePins computes a sorted SHA-256 inventory from the
// current source tree. The packet writer verifies these pins again before
// publication, so a source edit between preparation and emission fails closed.
func CurrentCompletedSourcePins(sourceRoot string) ([]SourcePin, error) {
	root, err := completedSourceRoot(sourceRoot)
	if err != nil {
		return nil, err
	}
	paths, err := completedSourcePaths(root)
	if err != nil {
		return nil, err
	}
	pins := make([]SourcePin, 0, len(paths))
	for _, path := range paths {
		name := filepath.Join(root, filepath.FromSlash(path))
		file, err := os.Open(name)
		if err != nil {
			return nil, err
		}
		digest := sha256.New()
		_, copyErr := io.Copy(digest, file)
		closeErr := file.Close()
		if err := errors.Join(copyErr, closeErr); err != nil {
			return nil, err
		}
		pins = append(pins, SourcePin{Path: path, SHA256: hex.EncodeToString(digest.Sum(nil))})
	}
	if err := VerifyCompletedSourcePins(root, pins); err != nil {
		return nil, err
	}
	return pins, nil
}

// VerifyCompletedSourcePins checks both hashes and full directory coverage.
// Unlike a fixed required-path list, it rejects a recipe that omits a newly
// added production source file from one of the completed recipe packages.
func VerifyCompletedSourcePins(sourceRoot string, pins []SourcePin) error {
	root, err := completedSourceRoot(sourceRoot)
	if err != nil {
		return err
	}
	paths, err := completedSourcePaths(root)
	if err != nil {
		return err
	}
	for _, path := range paths {
		if !slices.ContainsFunc(pins, func(pin SourcePin) bool { return pin.Path == path }) {
			return fmt.Errorf("completed source pins omit %q", path)
		}
	}
	return VerifySourcePins(root, pins)
}

func completedSourceRoot(sourceRoot string) (string, error) {
	root, err := filepath.Abs(sourceRoot)
	if err != nil {
		return "", err
	}
	info, err := os.Lstat(root)
	if err != nil || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
		return "", errors.New("source root must be a real directory")
	}
	resolved, err := filepath.EvalSymlinks(root)
	if err != nil || resolved != root {
		return "", errors.New("source root has a symlink ancestor")
	}
	return root, nil
}

func completedSourcePaths(root string) ([]string, error) {
	var paths []string
	for _, directory := range completedRecipeSourceDirs {
		if !canonicalPath(directory) {
			return nil, fmt.Errorf("invalid completed source directory %q", directory)
		}
		if err := filepath.WalkDir(filepath.Join(root, filepath.FromSlash(directory)),
			func(name string, item fs.DirEntry, walkErr error) error {
				if walkErr != nil {
					return walkErr
				}
				if item.Type()&os.ModeSymlink != 0 {
					return fmt.Errorf("completed source tree contains symlink %q", name)
				}
				if item.IsDir() {
					return nil
				}
				if !item.Type().IsRegular() {
					return fmt.Errorf("completed source tree contains nonregular file %q", name)
				}
				if !strings.HasSuffix(name, ".go") && !strings.HasSuffix(name, ".service") &&
					!strings.HasSuffix(name, ".sh") && !strings.HasSuffix(name, ".sysusers") &&
					!strings.HasSuffix(name, ".py") || strings.HasSuffix(name, "_test.go") ||
					strings.HasPrefix(filepath.Base(name), "test_") {
					return nil
				}
				relative, err := filepath.Rel(root, name)
				if err != nil {
					return err
				}
				path := filepath.ToSlash(relative)
				if !canonicalPath(path) {
					return fmt.Errorf("invalid completed source path %q", path)
				}
				paths = append(paths, path)
				return nil
			}); err != nil {
			return nil, err
		}
	}
	slices.Sort(paths)
	paths = slices.Compact(paths)
	if len(paths) > maxSourcePins {
		return nil, errors.New("completed source inventory exceeds packet pin bound")
	}
	for _, required := range requiredSourcePaths {
		if !slices.Contains(paths, required) {
			return nil, fmt.Errorf("completed source inventory omits baseline %q", required)
		}
	}
	return paths, nil
}

mount_guard.text:
func verifyMountedGuestRoot(root string) error {
	if root == "/" || !filepath.IsAbs(root) || filepath.Clean(root) != root {
		return errors.New("guest root must be an exact non-root mount point")
	}
	info, err := os.Lstat(root)
	if err != nil || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
		return errors.New("guest root must be a mounted real directory")
	}
	resolved, err := filepath.EvalSymlinks(root)
	if err != nil || resolved != root {
		return errors.New("guest root has a symlink ancestor")
	}
	parent, err := os.Stat(filepath.Dir(root))
	if err != nil {
		return err
	}
	rootStat, rootOK := info.Sys().(*syscall.Stat_t)
	parentStat, parentOK := parent.Sys().(*syscall.Stat_t)
	if !rootOK || !parentOK || rootStat.Dev == parentStat.Dev {
		return errors.New("guest root is not a distinct filesystem mount point")
	}
	var filesystem unix.Statfs_t
	if err := unix.Statfs(root, &filesystem); err != nil {
		return err
	}
	if filesystem.Type != unix.EXT4_SUPER_MAGIC {
		return errors.New("guest root mount is not an ext4 image")
	}
	return nil
}

guest_account.text:
func verifyGuestAccount(root string, wantUID, wantGID uint32) error {
	passwd, err := readGuestRegular(root, "/etc/passwd")
	if err != nil {
		return err
	}
	group, err := readGuestRegular(root, "/etc/group")
	if err != nil {
		return err
	}
	var uid, primaryGID, gid uint64
	var users, groups int
	for line := range strings.SplitSeq(string(passwd), "\n") {
		fields := strings.Split(line, ":")
		if fields[0] != serviceAccountName {
			continue
		}
		if len(fields) != 7 {
			return errors.New("guest service passwd entry is malformed")
		}
		users++
		uid, err = strconv.ParseUint(fields[2], 10, 32)
		if err != nil {
			return err
		}
		primaryGID, err = strconv.ParseUint(fields[3], 10, 32)
		if err != nil {
			return err
		}
	}
	for line := range strings.SplitSeq(string(group), "\n") {
		fields := strings.Split(line, ":")
		if fields[0] != serviceAccountName {
			continue
		}
		if len(fields) != 4 {
			return errors.New("guest service group entry is malformed")
		}
		groups++
		gid, err = strconv.ParseUint(fields[2], 10, 32)
		if err != nil {
			return err
		}
	}
	if users != 1 || groups != 1 || uid == 0 || gid == 0 ||
		uid != uint64(wantUID) || primaryGID != uint64(wantGID) || gid != uint64(wantGID) {
		return errors.New("guest service account UID/GID differs from signed directory plan")
	}
	return nil
}

guest_read.text:
func guestPath(root, absolute string, createParents bool) (string, error) {
	if !filepath.IsAbs(absolute) || filepath.Clean(absolute) != absolute || absolute == "/" {
		return "", fmt.Errorf("invalid guest path %q", absolute)
	}
	parts := strings.Split(strings.TrimPrefix(absolute, "/"), "/")
	current := root
	for _, part := range parts[:len(parts)-1] {
		current = filepath.Join(current, part)
		info, err := os.Lstat(current)
		if errors.Is(err, os.ErrNotExist) && createParents {
			if err := os.Mkdir(current, 0o755); err != nil {
				return "", err
			}
			if err := os.Chown(current, 0, 0); err != nil {
				return "", err
			}
			continue
		}
		if err != nil || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
			return "", fmt.Errorf("guest path %q has missing or unsafe ancestor", absolute)
		}
	}
	return filepath.Join(current, parts[len(parts)-1]), nil
}

func readGuestRegular(root, absolute string) ([]byte, error) {
	path, err := guestPath(root, absolute, false)
	if err != nil {
		return nil, err
	}
	info, err := os.Lstat(path)
	if err != nil || !info.Mode().IsRegular() {
		return nil, fmt.Errorf("guest path %q is not regular: %w", absolute, err)
	}
	if info.Size() < 0 || info.Size() > 8<<20 {
		return nil, fmt.Errorf("guest path %q exceeds bounded read", absolute)
	}
	return os.ReadFile(path)
}

